class RottenTomatoesProcessor(DataProcessor):
    """Processor for Rotten Tomatoes"""
    TASK_NAME = "rotten_tomatoes"
    TRAIN_FILE_NAME = "train.csv"
    DEV_FILE_NAME = "dev.csv"
    TEST_FILE_NAME = "test.csv"

    def get_train_examples(self, data_dir):
        return self._create_examples(os.path.join(data_dir, self.TRAIN_FILE_NAME), "train")

    def get_dev_examples(self, data_dir):
        return self._create_examples(os.path.join(data_dir, self.DEV_FILE_NAME), "dev")

    def get_test_examples(self, data_dir):
        return self._create_examples(os.path.join(data_dir, self.TEST_FILE_NAME), "test")

    def get_labels(self):
        return ["0", "1"]

    def _create_examples(self, path, set_type):
        examples = []
        with open(path, encoding="utf-8") as f:
            reader = csv.DictReader(f)
            for line in reader:
                examples.append(InputExample(
                    guid=f"{set_type}-{line['id']}",
                    text_a=line['text_a'],
                    text_b=None,
                    label=str(line['label'])
                ))
        return examples

